func (e *Extractor) Extract(ctx context.Context, transcriptText string, knownSkillNames ...[]string) (*SessionFacets, *llmcli.UsageInfo, error) {
	if e.Runner == nil {
		e.Runner = &llmcli.Runner{}
	}

	var prompt string
	if len(knownSkillNames) > 0 && len(knownSkillNames[0]) > 0 {
