		}
		byScopeKey[recordScopeKey(fingerprint, records[i].ScopeKind, records[i].ScopeValue)] = i
	}
	return byScopeKey
}

func findExactRecordScopeIndex(records []MemoryRecord, record MemoryRecord) (int, bool) {
